document.querySelector('#pausebtn').onclick=()=>toggleOverlay('pause');
function worldDraw(){let w=innerWidth,h=innerHeight;ctx.clearRect(0,0,w,h);let ox=cam.x,oy=cam.y;ctx.save();ctx.translate(-ox,-oy);
// layered meadow with soft woodland flecks
ctx.fillStyle='#496d54';ctx.fillRect(0,0,world.w,world.h);for(let i=0;i<70;i++){let x=seed(i+912)*world.w,y=seed(i+3321)*world.h;ctx.fillStyle=i%3?'#54795c':'#5b805f';ctx.globalAlpha=.22;ctx.beginPath();ctx.ellipse(x,y,100+seed(i)*150,60+seed(i+5)*100,seed(i+1)*3,0,7);ctx.fill()}ctx.globalAlpha=1;
// winding pale trail
ctx.lineCap='round';ctx.lineJoin='round';ctx.beginPath();for(let i=0;i<=80;i++){let p=pathPoint(i/80);i?ctx.lineTo(p.x,p.y):ctx.moveTo(p.x,p.y)}ctx.strokeStyle='#786f55';ctx.lineWidth=106;ctx.stroke();ctx.strokeStyle='#b9a77a';ctx.lineWidth=92;ctx.stroke();ctx.strokeStyle='#c9b989';ctx.globalAlpha=.5;ctx.lineWidth=2;ctx.setLineDash([5,14]);ctx.stroke();ctx.setLineDash([]);ctx.globalAlpha=1;
// shrine clearing and stone circle
ctx.fillStyle='#62775a';ctx.beginPath();ctx.ellipse(1190,805,190,145,0,0,7);ctx.fill();ctx.strokeStyle='#c4b998';ctx.lineWidth=9;ctx.beginPath();ctx.ellipse(1190,805,104,75,-.1,0,7);ctx.stroke();ctx.strokeStyle='#e2d2a7';ctx.lineWidth=3;ctx.stroke();ctx.fillStyle='#657570';ctx.fillRect(1173,735,34,48);ctx.fillStyle='#acb5a4';ctx.beginPath();ctx.moveTo(1170,735);ctx.lineTo(1190,710);ctx.lineTo(1210,735);ctx.fill();ctx.fillStyle='#e6c77e';ctx.shadowColor='#f9d782';ctx.shadowBlur=22;ctx.beginPath();ctx.arc(1190,755,6,0,7);ctx.fill();ctx.shadowBlur=0;
// tree canopy, rocks and flora
for(let o of decor){if(o.x<ox-60||o.x>ox+w+60||o.y<oy-70||o.y>oy+h+70)continue;let isBerry=o.kind>.92;if(isBerry&&o.gathered)continue;if(isBerry){ctx.fillStyle='#31543f';ctx.beginPath();ctx.ellipse(o.x,o.y,o.r*.75,o.r*.48,0,0,7);ctx.fill();for(let k=0;k<4;k++){ctx.fillStyle='#a74765';ctx.beginPath();ctx.arc(o.x-8+k*5,o.y-3+(k%2)*5,3,0,7);ctx.fill()}continue}if(o.kind<.48){ctx.fillStyle='#345340';ctx.beginPath();ctx.ellipse(o.x+4,o.y+13,o.r*.52,o.r*.28,0,0,7);ctx.fill();ctx.fillStyle='#735b43';ctx.fillRect(o.x-4,o.y-12,9,25);let g=ctx.createRadialGradient(o.x-7,o.y-o.r*.5,2,o.x,o.y-o.r*.35,o.r);g.addColorStop(0,'#83a46a');g.addColorStop(1,o.kind<.2?'#31583e':'#416849');ctx.fillStyle=g;ctx.beginPath();ctx.arc(o.x,o.y-o.r*.35,o.r,0,7);ctx.fill();ctx.fillStyle='#66875a';ctx.beginPath();ctx.arc(o.x-o.r*.35,o.y-o.r*.35,o.r*.58,0,7);ctx.fill()}else if(o.kind<.72){ctx.fillStyle='#797a68';ctx.beginPath();ctx.ellipse(o.x,o.y,o.r*.65,o.r*.43,0,0,7);ctx.fill();ctx.fillStyle='#a0a18a';ctx.beginPath();ctx.ellipse(o.x-4,o.y-3,o.r*.32,o.r*.19,0,0,7);ctx.fill()}else{ctx.fillStyle=o.kind>.84?'#e7c779':'#e9d8bd';ctx.beginPath();ctx.arc(o.x,o.y,2.4,0,7);ctx.fill();ctx.fillStyle='#98b076';ctx.fillRect(o.x-1,o.y,2,7)}}
// lanterns along the path
for(let i=0;i<11;i++){let p=pathPoint(i/10);ctx.fillStyle='#514c3c';ctx.fillRect(p.x-3,p.y-21,6,22);ctx.fillStyle='#f6d582';ctx.shadowColor='#ffda8a';ctx.shadowBlur=14;ctx.beginPath();ctx.arc(p.x,p.y-24,4,0,7);ctx.fill();ctx.shadowBlur=0}
for(let n of npcs)drawPerson(n.x,n.y,n.icon,'#dfbd74',true);
for(let e of enemies)drawEnemy(e);
for(let d of drops){ctx.fillStyle=d.type==='berry'?'#d881ac':'#f3d16f';ctx.shadowColor=ctx.fillStyle;ctx.shadowBlur=12;ctx.beginPath();ctx.arc(d.x,d.y-5,6+Math.sin(time*5)*1.5,0,7);ctx.fill();ctx.shadowBlur=0}
// player glow and directional sprite
if(player.skill>0&&jobs[selected].name==='Priest'){ctx.strokeStyle='#ffe79c99';ctx.lineWidth=3;ctx.beginPath();ctx.arc(player.x,player.y,50+Math.sin(time*10)*6,0,7);ctx.stroke()}
drawPerson(player.x,player.y,jobs[selected].icon,jobs[selected].color,false);
for(let p of particles){ctx.globalAlpha=Math.max(0,p.life*1.6);ctx.fillStyle=p.color;ctx.beginPath();ctx.arc(p.x,p.y,p.r,0,7);ctx.fill()}ctx.globalAlpha=1;
ctx.restore();
// vignette and nameplates
let grd=ctx.createRadialGradient(w/2,h/2,Math.min(w,h)*.3,w/2,h/2,Math.max(w,h)*.75);grd.addColorStop(0,'#10231a00');grd.addColorStop(1,'#101d2a40');ctx.fillStyle=grd;ctx.fillRect(0,0,w,h);
}
function drawPerson(x,y,icon,color,isNpc){ctx.fillStyle='#22352955';ctx.beginPath();ctx.ellipse(x,y+7,17,8,0,0,7);ctx.fill();ctx.fillStyle=color;ctx.beginPath();ctx.ellipse(x,y-7,11,15,0,0,7);ctx.fill();ctx.fillStyle='#e9c9a0';ctx.beginPath();ctx.arc(x,y-23,9,0,7);ctx.fill();ctx.fillStyle='#554438';ctx.beginPath();ctx.arc(x,y-27,9,Math.PI,Math.PI*2);ctx.fill();ctx.font='16px sans-serif';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(icon,x,y-9);if(isNpc){ctx.font='12px Marcellus';ctx.fillStyle='#fff0c8';ctx.shadowColor='#000';ctx.shadowBlur=4;ctx.fillText('Rowan',x,y-43);ctx.shadowBlur=0;ctx.fillStyle='#f6df9e';ctx.font='16px sans-serif';ctx.fillText('!',x,y-57)}}
function drawEnemy(e){let hurt=e.hit>0;ctx.fillStyle='#1b2c2d66';ctx.beginPath();ctx.ellipse(e.x,e.y+8,17,8,0,0,7);ctx.fill();ctx.fillStyle=hurt?'#ffb48c':e.type==='brute'?'#6c4a4b':'#6d6653';ctx.beginPath();ctx.ellipse(e.x,e.y-8,e.type==='brute'?15:11,e.type==='brute'?17:13,0,0,7);ctx.fill();ctx.fillStyle='#a8a28a';ctx.beginPath();ctx.arc(e.x,e.y-24,9,0,7);ctx.fill();ctx.fillStyle='#b94749';ctx.fillRect(e.x-4,e.y-26,3,3);ctx.fillRect(e.x+2,e.y-26,3,3);ctx.fillStyle='#211f27';ctx.fillRect(e.x-15,e.y-42,30,4);ctx.fillStyle='#c66a60';ctx.fillRect(e.x-15,e.y-42,30*Math.max(0,e.hp/e.max),4)}
function drawMap(){mx.fillStyle='#496d54';mx.fillRect(0,0,300,210);mx.strokeStyle='#b9a77a';mx.lineWidth=10;mx.beginPath();for(let i=0;i<=40;i++){let p=pathPoint(i/40);i?mx.lineTo(p.x/world.w*300,p.y/world.h*210):mx.moveTo(p.x/world.w*300,p.y/world.h*210)}mx.stroke();mx.fillStyle='#c9c1a8';mx.beginPath();mx.arc(1190/world.w*300,805/world.h*210,9,0,7);mx.fill();for(let e of enemies){mx.fillStyle='#c6655b';mx.fillRect(e.x/world.w*300-2,e.y/world.h*210-2,4,4)}mx.fillStyle='#ffe497';mx.beginPath();mx.arc(player.x/world.w*300,player.y/world.h*210,4,0,7);mx.fill();mx.strokeStyle='#fff7';mx.lineWidth=1;mx.strokeRect(cam.x/world.w*300,cam.y/world.h*210,innerWidth/world.w*300,innerHeight/world.h*210)}
function loop(stamp){if(!active)return;let dt=Math.min(.04,(stamp-last)/1000||.016);last=stamp;time+=dt;if(!paused){let x=(keys.d||keys.arrowright?1:0)-(keys.a||keys.arrowleft?1:0)+joystick.x,y=(keys.s||keys.arrowdown?1:0)-(keys.w||keys.arrowup?1:0)+joystick.y,mag=Math.hypot(x,y);if(mag){x/=Math.max(1,mag);y/=Math.max(1,mag);player.x+=x*190*dt;player.y+=y*190*dt;player.dir=Math.atan2(y,x)}player.x=Math.max(30,Math.min(world.w-30,player.x));player.y=Math.max(40,Math.min(world.h-40,player.y));player.attack=Math.max(0,player.attack-dt);player.skill=Math.max(0,player.skill-dt);player.invuln=Math.max(0,player.invuln-dt);player.mp=Math.min(player.maxmp,player.mp+dt*1.8);enemies.forEach(e=>{e.phase+=dt;e.hit=Math.max(0,e.hit-dt);let dx=player.x-e.x,dy=player.y-e.y,d=Math.hypot(dx,dy);if(d<260&&d>29){e.x+=dx/d*e.spd*dt;e.y+=dy/d*e.spd*dt}else if(d<=32){e.attack-=dt;if(e.attack<=0&&player.invuln<=0){player.hp-=e.type==='brute'?13:8;player.invuln=.7;e.attack=1.1;burst(player.x,player.y,'#ee776d',5);if(player.hp<=0){player.hp=player.maxhp;player.x=420;player.y=850;toast('The forest returns you to Rowan.')}}}});drops.forEach(d=>d.life-=dt);drops=drops.filter(d=>d.life>0);particles.forEach(p=>{p.life-=dt;p.x+=p.vx*dt;p.y+=p.vy*dt;p.vx*=.96;p.vy*=.96});particles=particles.filter(p=>p.life>0);cam.x=Math.max(0,Math.min(world.w-innerWidth,player.x-innerWidth/2));cam.y=Math.max(0,Math.min(world.h-innerHeight,player.y-innerHeight/2));toastTimer-=dt;if(toastTimer<=0)document.querySelector('#toast').classList.remove('show');ui()}worldDraw();drawMap();requestAnimationFrame(loop)}
addEventListener('keydown',e=>{let k=e.key.toLowerCase();keys[k]=true;if([' ','arrowup','arrowdown','arrowleft','arrowright'].includes(k))e.preventDefault();if(!active){if(k==='enter')start();return}if(k===' '||k==='j')attack();if(k==='q'||k==='k')castSkill();if(k==='e')interact();if(k==='i')toggleOverlay('bag');if(k==='escape'){if(paused){document.querySelector('#overlay').style.display='none';paused=false}else toggleOverlay('pause')}});addEventListener('keyup',e=>keys[e.key.toLowerCase()]=false);
let joy=document.querySelector('#joy'),nub=document.querySelector('#nub'),joyId=null;joy.addEventListener('pointerdown',e=>{joyId=e.pointerId;joy.setPointerCapture(joyId);moveJoy(e)});joy.addEventListener('pointermove',e=>{if(e.pointerId===joyId)moveJoy(e)});function moveJoy(e){let r=joy.getBoundingClientRect(),dx=e.clientX-(r.left+r.width/2),dy=e.clientY-(r.top+r.height/2),d=Math.hypot(dx,dy),scale=Math.min(1,45/(d||1));joystick.x=dx*scale/45;joystick.y=dy*scale/45;nub.style.transform=`translate(${dx*scale}px,${dy*scale}px)`}joy.addEventListener('pointerup',e=>{if(e.pointerId===joyId){joyId=null;joystick={x:0,y:0};nub.style.transform=''}});joy.addEventListener('pointercancel',()=>{joyId=null;joystick={x:0,y:0};nub.style.transform=''});
canvas.addEventListener('pointerdown',e=>{if(!active||paused)return;if(e.clientY<innerHeight-115){let wx=e.clientX+cam.x,wy=e.clientY+cam.y;player.dir=Math.atan2(wy-player.y,wx-player.x);if(e.detail===2)attack()}});
})();
</script></body></html>

