 function burst(x,y,color,n){for(let i=0;i<n;i++){let a=Math.random()*Math.PI*2,s=20+Math.random()*110;particles.push({x,y,vx:Math.cos(a)*s,vy:Math.sin(a)*s,life:.25+Math.random()*.55,color,r:2+Math.random()*3})}}
 function interact(){let npc=npcs.find(n=>Math.hypot(n.x-player.x,n.y-player.y)<85);if(npc){if(kills<3)toast(npc.line);else if(berries<3)toast('Bring me three moonberries from around the shrine!');else{toast('The shrine is safe again. Take this blessing, friend!');player.xp+=30;player.hp=player.maxhp;berries=0;kills=0;enemies=[];for(let i=0;i<15;i++)addEnemy(500+seed(i+221)*1600,350+seed(i+771)*1100,i%7===0?'brute':'wildling');save()}ui();return}let d=drops.findIndex(a=>Math.hypot(a.x-player.x,a.y-player.y)<55);if(d>=0){let a=drops.splice(d,1)[0];if(a.type==='berry'){berries++;toast('Moonberry gathered!')}else{toast('Found 3 silver!');player.xp+=3}ui();return}let berry=decor.find(o=>o.kind>.92&&Math.hypot(o.x-player.x,o.y-player.y)<55&&!o.gathered);if(berry){berry.gathered=true;berries++;toast('Moonberry gathered!');ui();return}toast('Nothing nearby. Follow the lantern path east.')}
 function toggleOverlay(kind){paused=true;let box=document.querySelector('#overlay'),c=document.querySelector('#overlaycontent');box.style.display='grid';if(kind==='bag'){c.innerHTML=`<div class="eyebrow">Your pack</div><h2>Adventurer's Satchel</h2><div class="inventory"><div class="invitem"><b>🫐 ${berries}</b>Moonberries</div><div class="invitem"><b>🪙 ${(player.level-1)*12}</b>Silver</div><div class="invitem"><b>🧪 2</b>Field tonics</div><div class="invitem"><b>📜 1</b>Old map</div></div><p>Items found in the Wildwood are kept here.</p><button class="start close">BACK TO THE WILD</button>`}else c.innerHTML=`<div class="eyebrow">Take a breath, traveler</div><h2>Adventure Paused</h2><p>You're safe for now. Your progress saves automatically.</p><button class="start close">CONTINUE</button> <button class="iconbtn restart">New adventure</button>`;c.querySelector('.close').onclick=()=>{box.style.display='none';paused=false};c.querySelector('.restart')?.addEventListener('click',()=>location.reload())}
 document.querySelector('#bagbtn').onclick=()=>toggleOverlay('bag');document.querySelector('#pausebtn').onclick=()=>toggleOverlay('pause');
